let state={results:[]},el={userId:document.getElementById("userId"),ticketCode:document.getElementById("ticketCode"),bulk:document.getElementById("bulk"),status:document.getElementById("status"),resultBody:document.getElementById("resultBody"),themeToggle:document.getElementById("themeToggle"),sendBtn:document.getElementById("sendBtn"),copyBtn:document.getElementById("copyBtn"),clearBtn:document.getElementById("clearBtn"),checkUserBtn:document.getElementById("checkUserBtn"),adminUrl:document.getElementById("adminUrl"),executorName:document.getElementById("executorName"),startDate:document.getElementById("startDate"),endDate:document.getElementById("endDate"),agentHeaders:document.getElementById("agentHeaders")};function todayISO(){var e=new Date;return e.getFullYear()+`-${String(e.getMonth()+1).padStart(2,"0")}-`+String(e.getDate()).padStart(2,"0")}function setStatus(e){el.status.textContent=e}el.startDate.value=todayISO(),el.endDate.value=todayISO(),el.adminUrl.value="https://agent.png777.com";